    wire logic signed [13:0] l0n7_w19 = 14'(l0n7_w18) + 14'(l0n7_w15);
    wire logic signed [13:0] r0_7 = 14'(l0n7_w19) >>> 7;
    wire logic [3:0] n0_7 = r0_7[13] ? 4'd0 : ((r0_7 > 14'sd15) ? {4{1'b1}} : r0_7[3:0]);
    logic [3:0] qn0_0;
    logic [3:0] qn0_1;
    logic [3:0] qn0_2;
    logic [3:0] qn0_3;
    logic [3:0] qn0_4;
    logic [3:0] qn0_5;
    logic [3:0] qn0_6;
    logic [3:0] qn0_7;
    always_ff @(posedge clk) begin
        qn0_0 <= n0_0;
        qn0_1 <= n0_1;
        qn0_2 <= n0_2;
        qn0_3 <= n0_3;
        qn0_4 <= n0_4;
        qn0_5 <= n0_5;
        qn0_6 <= n0_6;
        qn0_7 <= n0_7;
    end
    // layer 2: 3 neurons x 8 inputs, class scores (signed)
    wire logic signed [10:0] l1n0_w1 = 11'($signed({1'b0, qn0_0})) <<< 6;
    wire logic signed [12:0] l1n0_w2 = 13'($signed({1'b0, qn0_0})) <<< 8;
    wire logic signed [12:0] l1n0_w3 = 13'($signed({1'b0, qn0_1})) <<< 8;
    wire logic signed [12:0] l1n0_w4 = 13'($signed({1'b0, qn0_2})) <<< 8;
    wire logic signed [12:0] l1n0_w5 = 13'($signed({1'b0, qn0_3})) <<< 8;
    wire logic signed [10:0] l1n0_w6 = 11'($signed({1'b0, qn0_4})) <<< 6;
    wire logic signed [8:0] l1n0_w7 = 9'($signed({1'b0, qn0_5})) <<< 4;
    wire logic signed [12:0] l1n0_w8 = 13'($signed({1'b0, qn0_6})) <<< 8;
    wire logic signed [10:0] l1n0_w9 = 11'($signed({1'b0, qn0_7})) <<< 6;
    wire logic signed [12:0] l1n0_w10 = 13'($signed({1'b0, qn0_7})) <<< 8;
    wire logic signed [12:0] l1n0_w11 = 13'sd3531;
    wire logic signed [12:0] l1n0_w12 = 13'(l1n0_w2) - 13'(l1n0_w1);
    wire logic signed [12:0] l1n0_w13 = 13'(l1n0_w3) - 13'(l1n0_w4);
    wire logic signed [13:0] l1n0_w14 = 14'(l1n0_w5) + 14'(l1n0_w6);
    wire logic signed [12:0] l1n0_w15 = 13'(l1n0_w7) - 13'(l1n0_w8);
    wire logic signed [12:0] l1n0_w16 = 13'(l1n0_w10) - 13'(l1n0_w9);
    wire logic signed [13:0] l1n0_w17 = 14'(l1n0_w12) + 14'(l1n0_w13);
    wire logic signed [13:0] l1n0_w18 = 14'(l1n0_w14) + 14'(l1n0_w15);
    wire logic signed [13:0] l1n0_w19 = 14'(l1n0_w16) - 14'(l1n0_w11);
    wire logic signed [14:0] l1n0_w20 = 15'(l1n0_w17) + 15'(l1n0_w18);
    wire logic signed [14:0] l1n0_w21 = 15'(l1n0_w20) + 15'(l1n0_w19);
    wire logic signed [14:0] n1_0 = l1n0_w21;
    wire logic signed [9:0] l1n1_w1 = 10'($signed({1'b0, qn0_0})) <<< 5;
    wire logic signed [11:0] l1n1_w2 = 12'($signed({1'b0, qn0_0})) <<< 7;
    wire logic signed [10:0] l1n1_w3 = 11'($signed({1'b0, qn0_1})) <<< 6;
    wire logic signed [7:0] l1n1_w4 = 8'($signed({1'b0, qn0_2})) <<< 3;
    wire logic signed [9:0] l1n1_w5 = 10'($signed({1'b0, qn0_2})) <<< 5;
    wire logic signed [11:0] l1n1_w6 = 12'($signed({1'b0, qn0_3})) <<< 7;
    wire logic signed [13:0] l1n1_w7 = 14'($signed({1'b0, qn0_3})) <<< 9;
    wire logic signed [10:0] l1n1_w8 = 11'($signed({1'b0, qn0_4})) <<< 6;
    wire logic signed [12:0] l1n1_w9 = 13'($signed({1'b0, qn0_4})) <<< 8;
    wire logic signed [9:0] l1n1_w10 = 10'($signed({1'b0, qn0_5})) <<< 5;
    wire logic signed [9:0] l1n1_w11 = 10'($signed({1'b0, qn0_6})) <<< 5;
    wire logic signed [11:0] l1n1_w12 = 12'($signed({1'b0, qn0_6})) <<< 7;
    wire logic signed [12:0] l1n1_w13 = 13'($signed({1'b0, qn0_7})) <<< 8;
    wire logic signed [12:0] l1n1_w14 = 13'sd2707;
    wire logic signed [11:0] l1n1_w15 = 12'(l1n1_w2) - 12'(l1n1_w1);
    wire logic signed [10:0] l1n1_w16 = 11'(l1n1_w3) - 11'(l1n1_w4);
    wire logic signed [12:0] l1n1_w17 = 13'(l1n1_w5) + 13'(l1n1_w6);
    wire logic signed [13:0] l1n1_w18 = 14'(l1n1_w8) - 14'(l1n1_w7);
    wire logic signed [13:0] l1n1_w19 = 14'(l1n1_w9) + 14'(l1n1_w10);
    wire logic signed [11:0] l1n1_w20 = 12'(l1n1_w11) - 12'(l1n1_w12);
    wire logic signed [13:0] l1n1_w21 = 14'(l1n1_w13) + 14'(l1n1_w14);
    wire logic signed [12:0] l1n1_w22 = 13'(l1n1_w15) + 13'(l1n1_w16);
    wire logic signed [13:0] l1n1_w23 = 14'(l1n1_w17) + 14'(l1n1_w18);
    wire logic signed [13:0] l1n1_w24 = 14'(l1n1_w20) - 14'(l1n1_w19);
    wire logic signed [14:0] l1n1_w25 = 15'(l1n1_w22) + 15'(l1n1_w23);
    wire logic signed [13:0] l1n1_w26 = 14'(l1n1_w24) + 14'(l1n1_w21);
    wire logic signed [14:0] l1n1_w27 = 15'(l1n1_w25) + 15'(l1n1_w26);
    wire logic signed [14:0] n1_1 = l1n1_w27;
    wire logic signed [12:0] l1n2_w1 = 13'($signed({1'b0, qn0_0})) <<< 8;
    wire logic signed [12:0] l1n2_w2 = 13'($signed({1'b0, qn0_1})) <<< 8;
    wire logic signed [12:0] l1n2_w3 = 13'($signed({1'b0, qn0_2})) <<< 8;
    wire logic signed [11:0] l1n2_w4 = 12'($signed({1'b0, qn0_3})) <<< 7;
    wire logic signed [8:0] l1n2_w5 = 9'($signed({1'b0, qn0_4})) <<< 4;
    wire logic signed [10:0] l1n2_w6 = 11'($signed({1'b0, qn0_4})) <<< 6;
    wire logic signed [12:0] l1n2_w7 = 13'($signed({1'b0, qn0_5})) <<< 8;
    wire logic signed [12:0] l1n2_w8 = 13'($signed({1'b0, qn0_6})) <<< 8;
    wire logic signed [12:0] l1n2_w9 = 13'($signed({1'b0, qn0_7})) <<< 8;
    wire logic signed [12:0] l1n2_w10 = 13'sd2260;
    wire logic signed [12:0] l1n2_w11 = 13'(l1n2_w1) - 13'(l1n2_w2);
    wire logic signed [13:0] l1n2_w12 = 14'(l1n2_w3) + 14'(l1n2_w4);
    wire logic signed [10:0] l1n2_w13 = 11'(l1n2_w5) - 11'(l1n2_w6);
    wire logic signed [12:0] l1n2_w14 = 13'(l1n2_w8) - 13'(l1n2_w7);
    wire logic signed [13:0] l1n2_w15 = 14'(l1n2_w9) + 14'(l1n2_w10);
    wire logic signed [14:0] l1n2_w16 = 15'(l1n2_w11) + 15'(l1n2_w12);
    wire logic signed [13:0] l1n2_w17 = 14'(l1n2_w13) + 14'(l1n2_w14);
    wire logic signed [14:0] l1n2_w18 = 15'(l1n2_w16) + 15'(l1n2_w17);
    wire logic signed [14:0] l1n2_w19 = 15'(l1n2_w18) - 15'(l1n2_w15);
    wire logic signed [14:0] n1_2 = l1n2_w19;
    logic signed [14:0] qn1_0;
    logic signed [14:0] qn1_1;
    logic signed [14:0] qn1_2;
    always_ff @(posedge clk) begin
        qn1_0 <= n1_0;
        qn1_1 <= n1_1;
        qn1_2 <= n1_2;
    end
    // class scores and argmax, ties to the lowest class index
    wire logic signed [14:0] s0 = 15'(qn1_0);
    wire logic signed [14:0] s1 = 15'(qn1_1);
    wire logic signed [14:0] s2 = 15'(qn1_2);
    wire logic       ge10 = s1 > s0;
    wire logic signed [14:0] m01 = ge10 ? s1 : s0;
    wire logic [1:0] c01 = ge10 ? 2'd1 : 2'd0;
    wire logic [1:0] cls = (s2 > m01) ? 2'd2 : c01;
    logic [LATENCY-1:0] vpipe;
    always_ff @(posedge clk) begin
        out_cls <= cls;
        if (rst) vpipe <= '0; else vpipe <= {vpipe[LATENCY-2:0], in_v};
    end
    assign out_v = vpipe[LATENCY-1];
endmodule
`default_nettype wire
